#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Guardamos parámetros no sensibles de GCP en un archivo local ignorado por git (nunca secretos).
ENV_FILE="${ENV_FILE:-.env.gcp.local}"
TOTAL_STAGES=7

banner "PitchLab · Configuración inicial en Google Cloud Run (con candados de costo)"

# ── Stage 1: gcloud CLI y Proyecto ─────────────────────────────────────────
stage "Google Cloud CLI y Proyecto PitchLab"
say "Este asistente prepara Cloud Run (us-east4, junto a Neon us-east-1), Artifact Registry"
say "(retención de solo 3 imágenes), Cloud Storage (us-east1 Always Free 5 GB), deploy"
say "automático sin llaves JSON desde GitHub Actions y los 5 crons en Cloud Scheduler."
echo ""

if ! command -v gcloud >/dev/null 2>&1; then
  warn "No se encontró 'gcloud' instalado en esta computadora."
  step "En macOS con Homebrew puedes instalarlo en otra terminal con:"
  note "  brew install --cask google-cloud-sdk"
  open_url "https://cloud.google.com/sdk/docs/install"
  pause "Instala gcloud y presiona Enter cuando esté disponible en tu PATH (o Ctrl-C para volver luego)"
  if ! command -v gcloud >/dev/null 2>&1; then
    warn "'gcloud' sigue sin detectarse en PATH. Abre una nueva terminal tras instalarlo y vuelve a correr este script."
    exit 1
  fi
fi

step "Verificando sesión de Google Cloud..."
if ! gcloud auth list --filter=status:ACTIVE --format="value(account)" | grep -q .; then
  say "Se abrirá tu navegador para iniciar sesión en Google Cloud."
  gcloud auth login
fi

open_url "https://console.cloud.google.com/cloud-resource-manager"
step "Copia el ID del proyecto 'PitchLab' (columna 'ID', p. ej. pitchlab-123456; asegúrate de que esté ligado a 'Mi cuenta de facturación' con tus créditos)."
ask GCP_PROJECT_ID "ID del proyecto PitchLab en Google Cloud:"
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"

gcloud config set project "$GCP_PROJECT_ID" >/dev/null
PROJECT_NUMBER="$(gcloud projects describe "$GCP_PROJECT_ID" --format='value(projectNumber)')"
say "Proyecto activo: $GCP_PROJECT_ID (número: $PROJECT_NUMBER)"

GCP_REGION="us-east4"
GCP_STORAGE_REGION="us-east1"
GCP_AR_REPO="pitchlab"
GCP_CLOUD_RUN_SERVICE="pitchlab-web"
GITHUB_REPO="jairbonillacan-cmd/pitch"
GCS_AVATAR_BUCKET="${GCP_PROJECT_ID}-avatars"

write_env GCP_REGION "$GCP_REGION"
write_env GCP_AR_REPO "$GCP_AR_REPO"
write_env GCP_CLOUD_RUN_SERVICE "$GCP_CLOUD_RUN_SERVICE"
write_env GCS_AVATAR_BUCKET "$GCS_AVATAR_BUCKET"

# ── Stage 2: Habilitar APIs gratuitas ──────────────────────────────────────
stage "Habilitar las 5 APIs necesarias (activar APIs cuesta \$0)"
say "Activaremos: Cloud Run, Artifact Registry, Cloud Scheduler, IAM Credentials y Cloud Storage."
if confirm "¿Activar estas 5 APIs en el proyecto $GCP_PROJECT_ID?"; then
  gcloud services enable \
    run.googleapis.com \
    artifactregistry.googleapis.com \
    cloudscheduler.googleapis.com \
    iamcredentials.googleapis.com \
    storage.googleapis.com \
    --project="$GCP_PROJECT_ID"
  say "APIs activadas correctamente."
else
  SKIPPED+=("Activar APIs en proyecto $GCP_PROJECT_ID")
fi

# ── Stage 3: Artifact Registry + política de limpieza (máx. 3 imágenes) ───
stage "Artifact Registry con borrado automático de imágenes viejas"
say "Candado anti-sobrecargo: conservaremos SOLO las últimas 3 imágenes Docker para"
say "mantenernos dentro del nivel gratuito de 0.5 GB y evitar acumulación de cobros."

if ! gcloud artifacts repositories describe "$GCP_AR_REPO" \
  --location="$GCP_REGION" \
  --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
  gcloud artifacts repositories create "$GCP_AR_REPO" \
    --repository-format=docker \
    --location="$GCP_REGION" \
    --description="Imágenes de producción de PitchLab (retención automática de 3 versiones)" \
    --project="$GCP_PROJECT_ID"
else
  note "El repositorio '$GCP_AR_REPO' ya existe en $GCP_REGION; aplicando política de limpieza."
fi

POLICY_FILE="$(mktemp)"
cat > "$POLICY_FILE" <<'JSON'
[
  {
    "name": "conservar-ultimas-3",
    "action": { "type": "Keep" },
    "mostRecentVersions": { "keepCount": 3 }
  },
  {
    "name": "borrar-versiones-antiguas",
    "action": { "type": "Delete" },
    "condition": { "olderThan": "86400s" }
  }
]
JSON

gcloud artifacts repositories set-cleanup-policies "$GCP_AR_REPO" \
  --location="$GCP_REGION" \
  --project="$GCP_PROJECT_ID" \
  --policy="$POLICY_FILE" \
  --no-dry-run >/dev/null
rm -f "$POLICY_FILE"
say "Política de limpieza aplicada (máximo 3 imágenes retenidas)."
pause "Presiona Enter para continuar con el bucket de avatares"

# ── Stage 4: Bucket de Avatares en Cloud Storage (Always Free us-east1) ────
stage "Google Cloud Storage para avatares (us-east1 Always Free 5 GB)"
say "Usamos 'us-east1' clase Standard porque entra en los 5 GB Always Free de Google Cloud"
say "y queda justo al lado de Cloud Run (us-east4) y Neon (us-east-1)."

if ! gcloud storage buckets describe "gs://${GCS_AVATAR_BUCKET}" --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
  gcloud storage buckets create "gs://${GCS_AVATAR_BUCKET}" \
    --project="$GCP_PROJECT_ID" \
    --location="$GCP_STORAGE_REGION" \
    --default-storage-class=STANDARD \
    --uniform-bucket-level-access
else
  note "El bucket gs://${GCS_AVATAR_BUCKET} ya existe."
fi

# Lectura pública solo para las fotos de perfil (nunca listado de objetos privados)
gcloud storage buckets add-iam-policy-binding "gs://${GCS_AVATAR_BUCKET}" \
  --member="allUsers" \
  --role="roles/storage.objectViewer" >/dev/null

# Cuenta de servicio de runtime de Cloud Run con permiso de escritura sobre el bucket de avatares
RUNTIME_SA="${PROJECT_NUMBER}-compute@developer.gserviceaccount.com"
gcloud storage buckets add-iam-policy-binding "gs://${GCS_AVATAR_BUCKET}" \
  --member="serviceAccount:${RUNTIME_SA}" \
  --role="roles/storage.objectAdmin" >/dev/null

say "Bucket gs://${GCS_AVATAR_BUCKET} listo y conectado a la cuenta de runtime de Cloud Run."
pause "Presiona Enter para configurar el despliegue sin llaves desde GitHub Actions"

# ── Stage 5: Workload Identity Federation para GitHub Actions ──────────────
stage "Conexión sin llaves JSON entre GitHub Actions y Google Cloud"
say "Creamos un Workload Identity Provider bloqueado EXCLUSIVAMENTE al repo ${GITHUB_REPO}"
say "y una cuenta 'pitchlab-deployer' con permisos mínimos para desplegar Cloud Run."

DEPLOYER_SA_NAME="pitchlab-deployer"
DEPLOYER_SA_EMAIL="${DEPLOYER_SA_NAME}@${GCP_PROJECT_ID}.iam.gserviceaccount.com"
WIF_POOL="github-actions-pool"
WIF_PROVIDER="pitchlab-github"

if ! gcloud iam service-accounts describe "$DEPLOYER_SA_EMAIL" --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
  gcloud iam service-accounts create "$DEPLOYER_SA_NAME" \
    --display-name="PitchLab GitHub Actions Deployer" \
    --project="$GCP_PROJECT_ID"
fi

for role in "roles/run.admin" "roles/artifactregistry.writer" "roles/iam.serviceAccountUser"; do
  gcloud projects add-iam-policy-binding "$GCP_PROJECT_ID" \
    --member="serviceAccount:${DEPLOYER_SA_EMAIL}" \
    --role="$role" \
    --quiet >/dev/null
done

if ! gcloud iam workload-identity-pools describe "$WIF_POOL" --location=global --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
  gcloud iam workload-identity-pools create "$WIF_POOL" \
    --location=global \
    --display-name="GitHub Actions Pool" \
    --project="$GCP_PROJECT_ID"
fi

if ! gcloud iam workload-identity-pools providers describe "$WIF_PROVIDER" \
  --location=global \
  --workload-identity-pool="$WIF_POOL" \
  --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
  gcloud iam workload-identity-pools providers create-oidc "$WIF_PROVIDER" \
    --location=global \
    --workload-identity-pool="$WIF_POOL" \
    --display-name="PitchLab GitHub OIDC" \
    --issuer-uri="https://token.actions.githubusercontent.com" \
    --attribute-mapping="google.subject=assertion.sub,attribute.actor=assertion.actor,attribute.repository=assertion.repository" \
    --attribute-condition="assertion.repository == '${GITHUB_REPO}'" \
    --project="$GCP_PROJECT_ID"
fi

gcloud iam service-accounts add-iam-policy-binding "$DEPLOYER_SA_EMAIL" \
  --project="$GCP_PROJECT_ID" \
  --role="roles/iam.workloadIdentityUser" \
  --member="principalSet://iam.googleapis.com/projects/${PROJECT_NUMBER}/locations/global/workloadIdentityPools/${WIF_POOL}/attribute.repository/${GITHUB_REPO}" \
  --quiet >/dev/null

GCP_WIF_PROVIDER="projects/${PROJECT_NUMBER}/locations/global/workloadIdentityPools/${WIF_POOL}/providers/${WIF_PROVIDER}"
write_env GCP_WIF_PROVIDER "$GCP_WIF_PROVIDER"
write_env GCP_SERVICE_ACCOUNT "$DEPLOYER_SA_EMAIL"

# Escribir las variables públicas en GitHub Actions (activan .github/workflows/deploy-cloud-run.yml)
set_var GCP_PROJECT_ID "$GCP_PROJECT_ID"
set_var GCP_REGION "$GCP_REGION"
set_var GCP_AR_REPO "$GCP_AR_REPO"
set_var GCP_CLOUD_RUN_SERVICE "$GCP_CLOUD_RUN_SERVICE"
set_var GCP_WIF_PROVIDER "$GCP_WIF_PROVIDER"
set_var GCP_SERVICE_ACCOUNT "$DEPLOYER_SA_EMAIL"

say "Variables GCP_* guardadas en GitHub Actions."
pause "Presiona Enter para las variables públicas del navegador y el primer deploy"

# ── Stage 6: Variables NEXT_PUBLIC_* y primer despliegue ──────────────────
stage "Variables públicas del cliente y primer despliegue en Cloud Run"
say "Si usas Cloudflare Turnstile o Web Push (VAPID), sus claves PÚBLICAS se inyectan"
say "al compilar el contenedor. Si aún no las tienes, deja vacío y presiona Enter."
ask NEXT_PUBLIC_TURNSTILE_SITE_KEY "NEXT_PUBLIC_TURNSTILE_SITE_KEY (opcional):"
[[ -n "$NEXT_PUBLIC_TURNSTILE_SITE_KEY" ]] && set_var NEXT_PUBLIC_TURNSTILE_SITE_KEY "$NEXT_PUBLIC_TURNSTILE_SITE_KEY"
ask NEXT_PUBLIC_VAPID_PUBLIC_KEY "NEXT_PUBLIC_VAPID_PUBLIC_KEY (opcional):"
[[ -n "$NEXT_PUBLIC_VAPID_PUBLIC_KEY" ]] && set_var NEXT_PUBLIC_VAPID_PUBLIC_KEY "$NEXT_PUBLIC_VAPID_PUBLIC_KEY"

echo ""
if confirm "¿Disparar ahora el primer build y deploy en Cloud Run desde GitHub Actions?"; then
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    gh workflow run deploy-cloud-run.yml --ref main -f force=true
    say "Deploy iniciado en GitHub Actions (tarda ~3-5 min la primera vez)."
    open_url "https://github.com/${GITHUB_REPO}/actions/workflows/deploy-cloud-run.yml"
    pause "Espera a que termine en verde en GitHub Actions y presiona Enter"
  else
    SKIPPED+=("Disparar deploy-cloud-run.yml desde GitHub Actions")
  fi
fi

SERVICE_URL="$(gcloud run services describe "$GCP_CLOUD_RUN_SERVICE" \
  --project="$GCP_PROJECT_ID" \
  --region="$GCP_REGION" \
  --format='value(status.url)' 2>/dev/null || true)"

if [[ -n "$SERVICE_URL" ]]; then
  say "Servicio detectado en: $SERVICE_URL"
  open_url "https://console.cloud.google.com/run/detail/${GCP_REGION}/${GCP_CLOUD_RUN_SERVICE}/revisions?project=${GCP_PROJECT_ID}"
  step "En Cloud Run → 'Editar e implementar nueva revisión' → pestaña 'Variables y secretos', agrega tus variables de runtime (DATABASE_URL, BETTER_AUTH_SECRET, BETTER_AUTH_URL, CRON_SECRET, RESEND_API_KEY, GCS_AVATAR_BUCKET=${GCS_AVATAR_BUCKET}, PITCHLAB_PAYMENTS_MODE=transfer, PITCHLAB_TRANSFER_*, PITCHLAB_ADMIN_EMAILS, TURNSTILE_SECRET_KEY, VAPID_*)."
  note "Usar variables cifradas de Cloud Run (en vez de Secret Manager) ahorra ~\$1 USD/mes."
  pause "Presiona Enter cuando hayas verificado la URL o quieras crear los 5 crons"
fi

# ── Stage 7: Crear los 5 crons en Cloud Scheduler ($0.20 USD/mes total) ───
stage "Crear los 5 crons en Cloud Scheduler (\$0.20 USD/mes total)"
say "Cada despertador usa --max-retry-attempts=1 para evitar bucles costosos si falla algo."

if [[ -n "$SERVICE_URL" ]]; then
  note "URL detectada de Cloud Run: $SERVICE_URL (si ya conectaste https://pitchlab.mx, puedes escribirla abajo)."
fi
ask PITCHLAB_SITE_URL "URL pública de producción (ej. https://pitchlab.mx o tu URL .a.run.app):"
PITCHLAB_SITE_URL="${PITCHLAB_SITE_URL%/}"
write_env PITCHLAB_SITE_URL "$PITCHLAB_SITE_URL"
set_secret PITCHLAB_SITE_URL "$PITCHLAB_SITE_URL"

ask_secret CRON_SECRET_VAL "Pega tu CRON_SECRET (el mismo que pusiste en Cloud Run y GitHub; entrada oculta):"

if [[ -n "$PITCHLAB_SITE_URL" && -n "$CRON_SECRET_VAL" ]] && confirm "¿Crear o actualizar ahora los 5 crons en Cloud Scheduler ($GCP_REGION)?"; then
  upsert_cron() {
    local job="$1" sched="$2" path="$3" desc="$4"
    local uri="${PITCHLAB_SITE_URL}${path}"
    if gcloud scheduler jobs describe "$job" --location="$GCP_REGION" --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
      gcloud scheduler jobs update http "$job" \
        --location="$GCP_REGION" \
        --project="$GCP_PROJECT_ID" \
        --schedule="$sched" \
        --time-zone="Etc/UTC" \
        --uri="$uri" \
        --http-method=GET \
        --update-headers="Authorization=Bearer ${CRON_SECRET_VAL}" \
        --attempt-deadline=120s \
        --max-retry-attempts=1 \
        --description="$desc" >/dev/null
    else
      gcloud scheduler jobs create http "$job" \
        --location="$GCP_REGION" \
        --project="$GCP_PROJECT_ID" \
        --schedule="$sched" \
        --time-zone="Etc/UTC" \
        --uri="$uri" \
        --http-method=GET \
        --headers="Authorization=Bearer ${CRON_SECRET_VAL}" \
        --attempt-deadline=120s \
        --max-retry-attempts=1 \
        --description="$desc" >/dev/null
    fi
    say "✓ Cron listo: $job ($sched → $path)"
  }

  upsert_cron "pitchlab-settle-picks"    "0 */4 * * *"  "/api/cron/settle-picks"    "Liquidar picks/parlays y momios de cierre cada 4 h"
  upsert_cron "pitchlab-push-alerts"     "*/30 * * * *" "/api/cron/push-alerts"     "Alertas Web Push cada 30 min"
  upsert_cron "pitchlab-tipster-payouts" "0 15 * * *"   "/api/cron/tipster-payouts" "Comisiones de tipsters y correos programados (diario)"
  upsert_cron "pitchlab-weekly-digest"   "0 14 * * 1"   "/api/cron/weekly-digest"   "Resumen semanal de socios (lunes)"
  upsert_cron "pitchlab-monthly-record"  "0 15 1 * *"   "/api/cron/monthly-record"  "Corte mensual de Mi récord (día 1)"
  unset CRON_SECRET_VAL
else
  SKIPPED+=("Crear los 5 crons en Cloud Scheduler (vuelve a correr ./scripts/setup-google-cloud.sh)")
fi

finish
}

run_wizard "$@"; exit
